using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Markup;
using Microsoft.UI.Xaml.Media;
using Microsoft.UI.Xaml.Media.Imaging;
using System.Runtime.InteropServices.WindowsRuntime;
using System.Text.Json;
using Windows.Graphics;
using Windows.Graphics.Imaging;
using Windows.Storage;
using Windows.UI;
namespace RepeaterRefreshProbe;
static class Program {
 public static string Output="";
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr value);
 [STAThread]static void Main(string[] args){Output=Path.GetFullPath(args[0]);Directory.CreateDirectory(Output);SetProcessDpiAwarenessContext(new(-4));WinRT.ComWrappersSupport.InitializeComWrappers();Application.Start(_=>{SynchronizationContext.SetSynchronizationContext(new Microsoft.UI.Dispatching.DispatcherQueueSynchronizationContext(Microsoft.UI.Dispatching.DispatcherQueue.GetForCurrentThread()));new ProbeApplication();});}
}
public sealed partial class ProbeApplication:Application {
 Window window=null!;readonly Grid root=new(){Width=640,Height=480};readonly List<object> rows=[];readonly Dictionary<string,object> palettes=[];readonly List<object> galleryRefresh=[];
 public ProbeApplication(){InitializeComponent();UnhandledException+=(_,e)=>{File.WriteAllText(Path.Combine(Program.Output,"error.txt"),e.Exception.ToString());e.Handled=true;Exit();};}
 protected override void OnLaunched(LaunchActivatedEventArgs args){window=new Window{Title="Fixed SDK repeater and refresh probe",Content=root};window.AppWindow.ResizeClient(new SizeInt32(640,480));root.Loaded+=async(_,_)=>await Run();window.Activate();}
 static SolidColorBrush Solid(byte r,byte g,byte b)=>new(Color.FromArgb(255,r,g,b));
 async Task Image(FrameworkElement target,string name){var bmp=new RenderTargetBitmap();await bmp.RenderAsync(target);var folder=await StorageFolder.GetFolderFromPathAsync(Program.Output);var file=await folder.CreateFileAsync(name+".png",CreationCollisionOption.ReplaceExisting);using var stream=await file.OpenAsync(FileAccessMode.ReadWrite);var encoder=await BitmapEncoder.CreateAsync(BitmapEncoder.PngEncoderId,stream);encoder.SetPixelData(BitmapPixelFormat.Bgra8,BitmapAlphaMode.Premultiplied,(uint)bmp.PixelWidth,(uint)bmp.PixelHeight,96,96,(await bmp.GetPixelsAsync()).ToArray());await encoder.FlushAsync();}
 async Task Capture(FrameworkElement target,string theme,string kind,string state,ItemsRepeater? repeater=null){await Task.Delay(120);root.UpdateLayout();var elements=new List<object>();if(repeater!=null)for(int i=0;i<8;i++)if(repeater.TryGetElement(i) is FrameworkElement e){var b=e.TransformToVisual(repeater).TransformBounds(new(0,0,e.ActualWidth,e.ActualHeight));elements.Add(new{index=i,rect=new[]{b.X,b.Y,b.Width,b.Height}});}await Image(target,$"{theme}-{kind}-{state}");rows.Add(new{theme,kind,state,dpr=root.XamlRoot.RasterizationScale,size=new[]{target.ActualWidth,target.ActualHeight},desired=new[]{target.DesiredSize.Width,target.DesiredSize.Height},elements,visualizerState=(target as RefreshVisualizer)?.State.ToString()});}
 async Task Run(){try{
 foreach(var theme in new[]{ElementTheme.Light,ElementTheme.Dark}){
  var name=theme.ToString();root.RequestedTheme=theme;root.Background=theme==ElementTheme.Light?Solid(250,250,250):Solid(32,32,32);
  var brushes=new Dictionary<string,object>();foreach(var key in new[]{"SystemChromeLowColor","SystemControlBackgroundChromeMediumBrush","SystemControlBackgroundBaseLowBrush","SystemControlBackgroundAccentBrush","SystemControlForegroundChromeWhiteBrush","SystemControlForegroundAltHighBrush","TextFillColorInverseBrush","TextControlBorderBrush","SystemControlForegroundBaseHighBrush","ControlFillColorDefaultBrush","ControlStrokeColorDefaultBrush"}){var border=(Border)XamlReader.Load($"<Border xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' Background='{{ThemeResource {key}}}' Width='1' Height='1'/>");root.Children.Clear();root.Children.Add(border);await Task.Delay(20);root.UpdateLayout();if(border.Background is LinearGradientBrush gradient){double[] Matrix(Transform? tr){if(tr==null)return new[]{1d,0d,0d,1d,0d,0d};var o=tr.TransformPoint(new(0,0));var u=tr.TransformPoint(new(1,0));var v=tr.TransformPoint(new(0,1));return new[]{u.X-o.X,u.Y-o.Y,v.X-o.X,v.Y-o.Y,o.X,o.Y};}brushes[key]=new{kind="linearGradient",opacity=gradient.Opacity,mappingMode=gradient.MappingMode.ToString(),spreadMethod=gradient.SpreadMethod.ToString(),from=new[]{gradient.StartPoint.X,gradient.StartPoint.Y},to=new[]{gradient.EndPoint.X,gradient.EndPoint.Y},relativeTransform=Matrix(gradient.RelativeTransform),transform=Matrix(gradient.Transform),stops=gradient.GradientStops.Select(stop=>new{offset=stop.Offset,color=$"#{stop.Color.R:X2}{stop.Color.G:X2}{stop.Color.B:X2}{stop.Color.A:X2}"}).ToArray()};continue;}if(border.Background is not SolidColorBrush brush){brushes[key]=new{kind="solid",color="#00000000",opacity=1.0,nativeBrushValueNull=border.Background is null,nativeBrushType=border.Background?.GetType().Name??"null"};continue;}var c=brush.Color;brushes[key]=new{kind="solid",color=$"#{c.R:X2}{c.G:X2}{c.B:X2}{c.A:X2}",opacity=brush.Opacity};}palettes[name]=brushes;
  foreach(var orientation in new[]{Orientation.Vertical,Orientation.Horizontal}){
   var repeater=new ItemsRepeater{ItemsSource=Enumerable.Range(0,8).Select(i=>$"Item {i}").ToArray(),Layout=new StackLayout{Orientation=orientation,Spacing=8},ItemTemplate=(DataTemplate)XamlReader.Load("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><Border Width='80' Height='40' Background='#0078D7'><TextBlock Text='{Binding}' VerticalAlignment='Center' HorizontalAlignment='Center'/></Border></DataTemplate>"),Width=320,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top};root.Children.Clear();root.Children.Add(repeater);await Capture(repeater,name,"StackLayout",orientation.ToString(),repeater);
  }
  foreach(var orientation in new[]{Orientation.Horizontal,Orientation.Vertical})foreach(var stretch in new[]{UniformGridLayoutItemsStretch.None,UniformGridLayoutItemsStretch.Fill,UniformGridLayoutItemsStretch.Uniform})foreach(var justify in new[]{UniformGridLayoutItemsJustification.Start,UniformGridLayoutItemsJustification.Center}){
   var repeater=new ItemsRepeater{ItemsSource=Enumerable.Range(0,8).Select(i=>$"Item {i}").ToArray(),Layout=new UniformGridLayout{Orientation=orientation,MinItemWidth=80,MinItemHeight=40,MinColumnSpacing=8,MinRowSpacing=4,ItemsStretch=stretch,ItemsJustification=justify},ItemTemplate=(DataTemplate)XamlReader.Load("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><Border Background='#0078D7'><TextBlock Text='{Binding}' VerticalAlignment='Center' HorizontalAlignment='Center'/></Border></DataTemplate>"),Width=320,Height=180,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top};root.Children.Clear();root.Children.Add(repeater);await Capture(repeater,name,"UniformGridLayout",$"{orientation}-{stretch}-{justify}",repeater);
  }
  foreach(var kind in new[]{"FlowLayout","ActivityFeedLayout","VariedImageSizeLayout"}){Microsoft.UI.Xaml.Controls.Layout layout=kind=="FlowLayout"?new FlowLayout{MinItemSpacing=8,LineSpacing=8}:kind=="ActivityFeedLayout"?new WinUIGallery.Layouts.ActivityFeedLayout{MinItemSize=new(80,108),ColumnSpacing=12,RowSpacing=12}:new WinUIGallery.Layouts.VariedImageSizeLayout{Width=200};var rep=new ItemsRepeater{Width=520,Height=320,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top,Layout=layout,ItemsSource=Enumerable.Range(0,12).Select(i=>$"Item {i}").ToArray(),ItemTemplate=(DataTemplate)XamlReader.Load("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><Border Width='96' Height='64' Background='#0078D7'><TextBlock Text='{Binding}'/></Border></DataTemplate>")};root.Children.Clear();root.Children.Add(rep);await Capture(rep,name,kind,"GalleryDependency",rep);}
  var visualizer=new RefreshVisualizer{Width=320,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top};root.Children.Clear();root.Children.Add(visualizer);await Capture(visualizer,name,"RefreshVisualizer","Idle");
  var requested=0;Windows.Foundation.Deferral? deferral=null;visualizer.RefreshRequested+=(_,e)=>{requested++;deferral=e.GetDeferral();};visualizer.RequestRefresh();await Capture(visualizer,name,"RefreshVisualizer","Refreshing");deferral!.Complete();await Task.Delay(100);rows.Add(new{theme=name,kind="RefreshVisualizer",state="Completed",requests=requested,visualizerState=visualizer.State.ToString()});
  foreach(var direction in new[]{RefreshPullDirection.TopToBottom,RefreshPullDirection.BottomToTop,RefreshPullDirection.LeftToRight,RefreshPullDirection.RightToLeft}){var container=new RefreshContainer{Width=320,Height=180,PullDirection=direction,Content=new ScrollViewer{Content=new TextBlock{Text="Refresh content"}}};root.Children.Clear();root.Children.Add(container);await Capture(container,name,"RefreshContainer",direction.ToString());}
  using(var source=JsonDocument.Parse(File.ReadAllText(Path.GetFullPath(Path.Combine(Program.Output,"../../gallery/src/official-repeater-refresh.json"))))){foreach(var sample in new[]{"BasicPulltorefresh","CustomIconPulltorefresh"}){var xaml=source.RootElement.GetProperty(sample).GetProperty("runtimeXaml").GetString()!;xaml=xaml.Replace(" RefreshRequested=\"rc_RefreshRequested\"", "");var grid=sample=="BasicPulltorefresh"?(Grid)XamlReader.Load(xaml):new Grid();if(sample=="CustomIconPulltorefresh")grid.Children.Add(new RefreshContainer{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Content=new ListView{Width=200,Height=200}});var container=(RefreshContainer)grid.Children[0];var list=(ListView)container.Content;list.ItemsSource=source.RootElement.GetProperty("_repository").GetProperty("data").GetProperty(sample=="BasicPulltorefresh"?"refreshControls":"refreshFriends").EnumerateArray().Select(v=>v.GetString()).ToArray();root.Children.Clear();root.Children.Add(grid);await Task.Delay(120);root.UpdateLayout();galleryRefresh.Add(new{theme=name,sample,available=new[]{640d,480d},container=new[]{container.ActualWidth,container.ActualHeight},list=new[]{list.ActualWidth,list.ActualHeight},desired=new[]{container.DesiredSize.Width,container.DesiredSize.Height}});await Image(grid,$"{name}-GalleryRefresh-{sample}");}}
 }
 File.WriteAllText(Path.Combine(Program.Output,"gallery-refresh-measures.json"),JsonSerializer.Serialize(galleryRefresh,new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(Program.Output,"results.json"),JsonSerializer.Serialize(new{sdk="Microsoft.WindowsAppSDK.WinUI/2.3.10-experimental",scope="Same-SDK layout and refresh lifecycle probe; RenderTargetBitmap does not capture Composition rotation or demonstrate Store parity.",palettes,rows},new JsonSerializerOptions{WriteIndented=true}));Exit();
 }catch(Exception e){File.WriteAllText(Path.Combine(Program.Output,"error.txt"),e.ToString());Exit();}}
}
